sys_ws_operation.operation_script:
(function process(/*RESTAPIRequest*/ request, /*RESTAPIResponse*/ response) {

    try {
        var requestBody = request.body.data;

        // Log the incoming payload for debugging
        gs.info("Incoming Event Payload: " + JSON.stringify(requestBody));

        // Validation: check required fields
        if (!requestBody.u_event_name || !requestBody.u_contact_person) {
            response.setStatus(400);
            return { error: 'Missing required fields: u_event_name or u_contact_person.' };
        }

        var eventGR = new GlideRecord('x_1790116_event_ma_event');
        eventGR.initialize();

        // Map fields from payload
        eventGR.u_event_name = requestBody.u_event_name;
        // eventGR.u_event_date = requestBody.u_event_date || '';
        eventGR.u_location = requestBody.u_location || '';
        eventGR.u_contact_person = requestBody.u_contact_person;
        eventGR.u_contact_number = requestBody.u_contact_number || '';
        eventGR.u_email = requestBody.u_email || '';

        // Insert record
        var newSysId = eventGR.insert();

        if (newSysId) {
            response.setStatus(201);
            return {
                message: 'Event created successfully',
                sys_id: newSysId
            };
        } else {
            response.setStatus(500);
            return { error: 'Insert failed' };
        }

    } catch (err) {
        // Catch block with safe error logging
        gs.error("REST API Error: " + err);
        response.setStatus(500);
        return { error: 'Unexpected server error. Please check logs.' };
    }

})(request, response);
